import pytest

from tests.conftest import auth_headers


def _payload(user):
    return {
        "name": "sample name",
    }


@pytest.mark.skip(reason="Needs an existing products row; extend this test with one.")
async def test_review_crud(client, make_user):
    user = await make_user("review_owner")
    headers = auth_headers(user)

    r = await client.post("/reviews/", json=_payload(user), headers=headers)
    assert r.status_code == 201, r.text
    item_id = r.json()["id"]

    assert (await client.get(f"/reviews/{item_id}", headers=headers)).status_code == 200
    listed = (await client.get("/reviews/", headers=headers)).json()
    assert item_id in [row["id"] for row in listed]

    r = await client.patch(f"/reviews/{item_id}", json={"name": "updated name"}, headers=headers)
    assert r.status_code == 200, r.text
    assert r.json()["name"] == "updated name"

    r = await client.put(f"/reviews/{item_id}", json=_payload(user), headers=headers)
    assert r.status_code == 200, r.text

    assert (await client.delete(f"/reviews/{item_id}", headers=headers)).status_code == 200
    assert (await client.get(f"/reviews/{item_id}", headers=headers)).status_code == 404


async def test_review_requires_login(client):
    assert (await client.get("/reviews/")).status_code == 401
